/// Find an exact locale tag or return UnknownLocale; result has static lifetime.
pub fn get(tag: []const u8) t.Error!*const t.Locale {
    for (&all) |*l| if (std.mem.eql(u8, tag, l.tag)) return l;
    return error.UnknownLocale;
}
/// Find a locale, using only the explicitly requested fallback tag.
pub fn getOr(tag: []const u8, fallback: []const u8) t.Error!*const t.Locale {
    return get(tag) catch get(fallback);
}
